"""Generate a static, subpath-safe informational site. No backend or secrets."""
from pathlib import Path
from html import escape
root = Path(__file__).resolve().parents[1] / 'site'
nav = [('Features','features.html'),('Integrations','integrations.html'),('Documentation','docs.html'),('Download','download.html')]
footer = [('Changelog','changelog.html'),('Privacy','privacy.html'),('Security','security.html'),('FAQ','faq.html'),('About & contact','about.html')]
def links(items): return ''.join(f'<a href="{u}">{escape(t)}</a>' for t,u in items)
def render(title, description, body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)} | DOTX Browser"><meta property="og:description" content="{escape(description,quote=True)}"><meta name="theme-color" content="#09111e"><title>{escape(title)} | DOTX Browser</title><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap topbar"><a href="index.html" class="brand"><img src="assets/mark.svg" alt=""><span>DOTX<small>BY DOTSOFTWARELK</small></span></a><nav class="nav" aria-label="Main navigation">{links(nav)}</nav><details class="mobile-nav"><summary>Menu</summary><div>{links(nav+footer)}</div></details></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap footer-inner"><div><a href="index.html" class="brand"><img src="assets/mark.svg" alt=""><span>DOTX<small>BY DOTSOFTWARELK</small></span></a><p>A browser project in development. Built for a more focused workspace.</p></div><nav class="footer-links" aria-label="Footer navigation">{links(footer)}</nav></div></footer></body></html>'''
def page(title, intro, content):
    return f'<div class="wrap page"><div class="page-header"><span class="eyebrow">DOTX / {escape(title)}</span><h1>{escape(title)}</h1><p class="lead">{intro}</p></div><div class="content">{content}</div></div>'
home = '''<div class="wrap"><section class="hero"><div><span class="eyebrow">Introducing DOTX Browser</span><h1>A clearer space<br>to get things done.</h1><p>Meet DOTX: a Windows browser project from dotsoftwarelk, designed to bring the web and your everyday tools into focus.</p><div class="actions"><a class="button primary" href="download.html">Download information &nbsp; ↗</a><a class="button" href="features.html">Explore DOTX</a></div><div class="fine">In development · Windows release not yet verified</div></div><div><div class="preview" aria-hidden="true"><div class="preview-top"><i></i><i></i><i></i><span>Workspace</span></div><div class="preview-address">Search or enter an address</div><div class="preview-content"><div class="preview-side">OVERVIEW<br>Workspace<br>Bookmarks<br>History</div><div class="preview-main"><small>YOUR WORKSPACE</small><h3>All in one place.</h3><div class="mock-grid"><div class="mock-card">01 &nbsp; Documents</div><div class="mock-card">02 &nbsp; Projects</div><div class="mock-card">03 &nbsp; Files</div><div class="mock-card">04 &nbsp; Code</div></div></div></div></div><div class="concept">Concept illustration · not an application screenshot</div></div></section></div><div class="band"><div class="wrap"><strong>Designed for your daily flow</strong><span>Browser essentials</span><span>Quick access to your tools</span><span>Transparent release status</span></div></div><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Thoughtful by design</span><h2>Less friction. More focus.</h2></div><a href="features.html">View all features →</a></div><div class="grid"><article class="card"><span class="num">01 / BROWSE</span><h3>One familiar starting point</h3><p>Navigate, search, and move between tabs in a streamlined desktop window.</p></article><article class="card"><span class="num">02 / RETURN</span><h3>Keep useful pages close</h3><p>Save bookmarks and revisit browsing history stored on your device.</p></article><article class="card"><span class="num">03 / WORKSPACE</span><h3>Get to your tools faster</h3><p>Quick-launch your services in the browser. API connections are not yet implemented.</p></article></div></div></section><section class="section alt"><div class="wrap"><div class="callout"><div><span class="eyebrow">Built with clarity</span><h2>Know exactly where things stand.</h2><p>Read the current capabilities, limitations, and release status before you install.</p></div><a class="button primary" href="docs.html">Read the documentation →</a></div></div></section>'''
pages = {
'features.html': ('Features','A practical foundation for a more focused browsing experience.', '''<h2>Available in the development prototype</h2><p>Tabbed browsing with draggable tabs, address and search input, back, forward and reload. Save bookmarks, search and delete bookmark or history entries, select a search engine, and choose where to save downloads.</p><h2>Workspace quick launch</h2><p>Open Dropbox, Google Docs, Google Drive, Linear, Notion, GitHub and Supabase websites in new tabs. These are links only, not native API integrations or connected-account indicators.</p><h2>Not yet implemented</h2><p>Private browsing, session restore, advanced download management, permission settings, tab search, sync, account connections, updates and a complete accessibility review remain future work. See the documentation before use.</p>'''),
'integrations.html': ('Integrations','A starting point for accessing the tools you already use.', '''<div class="notice"><p><strong>Current status:</strong> The workspace offers website shortcuts only. DOTX does not yet connect to provider APIs, manage tokens, search provider data, or sync accounts.</p></div>''' + ''.join(f'<h2>{name}</h2><p>Open the official {name} website from the workspace. Authentication and permissions are handled by that website. Native API access, connection status, required scopes and setup are not yet implemented.</p>' for name in ['Dropbox','Google Docs','Google Drive','Linear','Notion','GitHub','Supabase']) + '<p>These providers do not endorse DOTX. All names belong to their respective owners.</p>'),
'download.html': ('Download','Windows release information.', '''<div class="notice"><p><strong>No verified Windows installer is available.</strong> This project is a development prototype, not a published release. No download link will appear until a real Windows build and release asset are verified.</p></div><h2>For developers</h2><p>The source tree includes Python and Qt for Python setup instructions. It has not yet been packaged or tested as a Windows installer. See <a href="docs.html">documentation</a>.</p><h2>Release integrity</h2><p>Checksums, code-signing information and release notes must be supplied for an actual release; none are available at present.</p>'''),
'changelog.html': ('Changelog','Changes and release history.', '<h2>Development prototype</h2><p>Initial source prototype. No public releases or verified version numbers have been established.</p>'),
'docs.html': ('Documentation','Get oriented with the current development prototype.', '''<h2>Setup</h2><p>Install Python and the dependencies in <code>requirements.txt</code>, then run <code>python -m dotx</code> from the <code>desktop</code> directory. This is a development workflow, not a verified Windows installer.</p><h2>Browser basics</h2><p>Use the address bar to enter a web address or search. Open tabs with the plus button; drag tabs to reorder them. Use the star to bookmark a page. The workspace buttons open provider websites.</p><h2>Data and troubleshooting</h2><p>History and bookmarks are stored locally. Browser engine data can also persist. If a site does not load, check your network and certificate settings; the prototype does not bypass certificate errors. Advanced controls and private browsing are not yet available.</p><h2>Updates and integration setup</h2><p>No update system or native service authorization exists yet. Refer to the project source documentation for current limitations.</p>'''),
'privacy.html': ('Privacy','Understand what the prototype stores and sends.', '''<h2>Local data</h2><p>Browsing history, bookmarks and the search-engine selection are saved locally. Qt WebEngine may also store cookies, cache and other website data in its profile. The application has no private browsing mode or complete clear-browsing-data controls.</p><h2>External services</h2><p>Navigation and searches are sent to the websites and search provider you choose. Workspace links open third-party sites, which apply their own privacy policies. No DOTX cloud synchronization or provider API token storage is implemented.</p><h2>Account disconnection</h2><p>Sign out using each provider website. DOTX does not currently manage third-party account connections or revoke authorizations.</p>'''),
'security.html': ('Security','Transparent security information for a project in development.', '''<h2>Current status</h2><p>DOTX is a development prototype and has not undergone an independent security audit. Do not use it for sensitive browsing until its security and permissions have been reviewed and tested.</p><h2>Reporting</h2><p>A dedicated security contact has not yet been configured. The project owner must publish a private reporting method before public release. Do not post secrets or exploit details publicly.</p><h2>Release integrity</h2><p>No signed or verified Windows release exists yet. Do not rely on unofficial installers.</p>'''),
'faq.html': ('FAQ','Answers about the current project.', '''<h2>Is there an installer?</h2><p>Not yet. No verified Windows installer or release is available.</p><h2>Are my services connected?</h2><p>No. Workspace buttons are shortcuts to provider websites, not API connections.</p><h2>Does it support private browsing or sync?</h2><p>Neither feature is implemented. Local history and web profile data can persist.</p><h2>Does the app require Supabase?</h2><p>No. There is no Supabase backend in this prototype.</p><h2>Will it run on my PC?</h2><p>Windows compatibility and hardware performance have not yet been verified.</p>'''),
'about.html': ('About & contact','DOTX Browser is a project by dotsoftwarelk.', '''<h2>About</h2><p>DOTX is a browser project in development. This site documents its current prototype and does not represent a completed release.</p><h2>Contact</h2><p>A verified support or security contact has not yet been provided. The owner must add one before publication.</p>'''),
'404.html': ('Page not found','The page you requested could not be found.', '<p>Return to the <a href="index.html">DOTX home page</a> or explore the <a href="docs.html">documentation</a>.</p>'),
}
root.mkdir(exist_ok=True)
(root/'index.html').write_text(render('Home','DOTX Browser by dotsoftwarelk: a Windows browser project in development.',home), encoding='utf-8')
for filename,(title,intro,content) in pages.items():
    (root/filename).write_text(render(title, intro, page(title,intro,content)), encoding='utf-8')
(root/'robots.txt').write_text('User-agent: *\nAllow: /\n', encoding='utf-8')
print('Generated', len(pages)+1, 'HTML pages')
